-- General organizational feedback and paused close contracts; all fixtures roll back.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create temp table feedback_state(key text primary key,value jsonb);
create function pg_temp.fb_actor(a uuid)returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true)::text is not null$$;
create function pg_temp.fb_cmd(cmd text,body jsonb default '{}',key uuid default gen_random_uuid())returns jsonb language sql as $$select api.frightnight_command('frightnight-2027-test',cmd,body,key)$$;
create function pg_temp.fb_pay(a uuid)returns void language plpgsql as $$declare o jsonb;begin
 o:=api.frightnight_payment_create('frightnight-2027-test',a,gen_random_uuid());
 perform api.frightnight_payment_bind('frightnight-2027-test',(o->>'order_id')::uuid,'ct_'||(o->>'order_id'),null);
 perform api.frightnight_payment_confirm('frightnight-2027-test','ct_'||(o->>'order_id'),'paid',(o->>'amount_cents')::integer,'EUR','feedback-paid:'||(o->>'order_id'),jsonb_build_object('order_id',o->>'order_id','event_id',o->>'event_id','testmode',true,'environment','staging'));
end $$;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data)select('f7340000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'feedback-'||n||'@example.invalid',now(),'{}','{}'from generate_series(1,5)n;
insert into app_private.events(id,slug,title,local_date,price_cents)values('f7340000-0000-0000-0000-000000000010','feedback-local-legacy','Synthetic protected feedback sentinel','2026-10-31',350);
insert into app_private.event_capabilities(event_id,user_id,capability)values('f7340000-0000-0000-0000-000000000010','f7340000-0000-0000-0000-000000000001','event_admin');
select api.frightnight_bootstrap('frightnight-2027-test','f7340000-0000-0000-0000-000000000001','staging','nocteiuvohesvqbowchw:staging:duindorphalloweenstg')is not null;
select api.frightnight_bootstrap('frightnight-2027-test-feedback-foreign','f7340000-0000-0000-0000-000000000001','staging','nocteiuvohesvqbowchw:staging:duindorphalloweenstg')is not null;
insert into feedback_state values('protected',jsonb_build_object('outbox',(select count(*)from app_private.email_outbox),'payments',(select count(*)from app_private.payment_requests),'auth',(select count(*)from auth.users),'legacyPhase',(select phase from app_private.events where id='f7340000-0000-0000-0000-000000000010')));
select ok((select relrowsecurity from pg_class where oid='app_private.fn_organization_thanks'::regclass),'new organization thanks table has RLS');
select ok(not has_table_privilege('authenticated','app_private.fn_organization_thanks','SELECT,INSERT,UPDATE,DELETE'),'browser cannot directly read or write organizational feedback');
select ok(not has_function_privilege('service_role','app_private.fn_general_thanks(text,jsonb,uuid)','EXECUTE'),'general thanks private implementation is not service callable');
select set_config('request.jwt.claims','{"role":"anon"}',true);
select throws_ok($$select pg_temp.fb_cmd('thanks.general','{"text":"Anonymous"}')$$,'42501','LOGIN_REQUIRED','anonymous general feedback is refused');
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000002');
select throws_ok($$select api.frightnight_command('frightnight-2027-test-feedback-foreign','thanks.general','{"text":"Foreign"}',gen_random_uuid())$$,'42501','EDITION_ACCESS_REQUIRED','general feedback cannot enter a foreign private edition');
select pg_temp.fb_cmd('registration.save','{"label":"Synthetic family A","routeType":"lantern","adults":1,"children":1,"maxIntensity":1,"consent":true,"termsVersion":"2027-test-v1"}');
select ok(api.frightnight_snapshot('frightnight-2027-test')->'registration'<>'null'::jsonb,'own registration is projected by the server');
select throws_ok($$select pg_temp.fb_cmd('thanks.general','{"text":"  "}')$$,'22023','INVALID_GENERAL_THANKS','empty organizational thanks is refused');
select throws_ok($$select pg_temp.fb_cmd('thanks.general',jsonb_build_object('text',repeat('x',501)))$$,'22023','INVALID_GENERAL_THANKS','organizational thanks is bounded to five hundred characters');
select throws_ok($$select pg_temp.fb_cmd('thanks.general','{"text":"Thank you","registrationId":"f7340000-0000-0000-0000-000000000099"}')$$,'22023','INVALID_GENERAL_THANKS','browser cannot target another registration or actor');
insert into feedback_state select 'general',pg_temp.fb_cmd('thanks.general','{"text":"Bedankt voor de hele avond"}','f7340000-0000-0000-0000-000000000101');
select is((select value#>>'{result,delivery}'from feedback_state where key='general'),'in-app','general thanks explicitly records durable in-app delivery');
select is((select value#>>'{result,mailSent}'from feedback_state where key='general'),'false','general thanks never claims external email');
select is(api.frightnight_snapshot('frightnight-2027-test')->>'organizationThanksSent','true','own sent state survives a fresh server read');
select ok(not(api.frightnight_snapshot('frightnight-2027-test')?'feedback'),'family cannot read organizational feedback or evaluations');
select is(pg_temp.fb_cmd('thanks.general','{"text":"Bedankt voor de hele avond"}','f7340000-0000-0000-0000-000000000101')->'result',(select value->'result'from feedback_state where key='general'),'exact receipt retry returns the stable result');
select lives_ok($$select pg_temp.fb_cmd('thanks.general','{"text":"Bedankt voor de hele avond"}')$$,'same text with a new command key remains one organizational delivery');
select throws_ok($$select pg_temp.fb_cmd('thanks.general','{"text":"Changed"}','f7340000-0000-0000-0000-000000000101')$$,'40001','IDEMPOTENCY_CONFLICT','same receipt key cannot change payload');
select throws_ok($$select pg_temp.fb_cmd('thanks.general','{"text":"Changed"}')$$,'40001','GENERAL_THANKS_ALREADY_SENT','a second different general message cannot create a second delivery');
select throws_ok($$select pg_temp.fb_cmd('help.submit','{"text":"Another command"}','f7340000-0000-0000-0000-000000000101')$$,'40001','IDEMPOTENCY_CONFLICT','general and core commands share one idempotency-key namespace');
update auth.users set banned_until=clock_timestamp()+interval'1 hour'where id='f7340000-0000-0000-0000-000000000002';
select throws_ok($$select pg_temp.fb_cmd('thanks.general','{"text":"Bedankt voor de hele avond"}','f7340000-0000-0000-0000-000000000101')$$,'42501','EDITION_ACCESS_REQUIRED','banned actor cannot replay a former organizational thanks receipt');
update auth.users set banned_until=null where id='f7340000-0000-0000-0000-000000000002';
select is((select count(*)from app_private.fn_organization_thanks),1::bigint,'all retries leave exactly one organizational message');
select is((select count(*)from app_private.fn_audit where action='thanks.general'),1::bigint,'all retries leave one general delivery audit');
select ok(not exists(select 1 from app_private.fn_receipts where result::text like'%Bedankt voor de hele avond%'),'receipts do not persist message content or broad snapshots');
insert into feedback_state select 'adultInvite',pg_temp.fb_cmd('registration.invite')->'result';
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000004');
select pg_temp.fb_cmd('registration.accept',jsonb_build_object('token',(select value->>'token'from feedback_state where key='adultInvite'),'consent',true));
select is(api.frightnight_snapshot('frightnight-2027-test')->>'organizationThanksSent','true','authorized adult sees the shared once-only general thanks state');
select lives_ok($$select pg_temp.fb_cmd('thanks.general','{"text":"Bedankt voor de hele avond"}','f7340000-0000-0000-0000-000000000103')$$,'authorized second adult can confirm the same organizational thanks');
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000002');
select pg_temp.fb_cmd('registration.revoke','{"userId":"f7340000-0000-0000-0000-000000000004"}');
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000004');
select throws_ok($$select pg_temp.fb_cmd('thanks.general','{"text":"Bedankt voor de hele avond"}','f7340000-0000-0000-0000-000000000103')$$,'42501','REGISTRATION_REQUIRED','revoked second adult cannot replay its former general thanks receipt');
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000003');
select pg_temp.fb_cmd('registration.save','{"label":"Synthetic family B","routeType":"lantern","adults":1,"children":1,"maxIntensity":1,"consent":true,"termsVersion":"2027-test-v1"}');
select is(api.frightnight_snapshot('frightnight-2027-test')->>'organizationThanksSent','false','another family cannot infer or read the first family message');
select ok(not(api.frightnight_snapshot('frightnight-2027-test')?'feedback'),'second family has no organization inbox');
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000001');
select is(jsonb_array_length(api.frightnight_snapshot('frightnight-2027-test')#>'{feedback,organizationThanks}'),1,'event administrator sees the actual organizational message');
select is(api.frightnight_snapshot('frightnight-2027-test')#>>'{feedback,organizationThanks,0,message}','Bedankt voor de hele avond','regie reads durable general thanks content');
select is(jsonb_array_length(api.frightnight_snapshot('frightnight-2027-test-feedback-foreign')#>'{feedback,organizationThanks}'),0,'organization inbox is strictly edition scoped');
insert into app_private.event_capabilities(event_id,user_id,capability)select id,'f7340000-0000-0000-0000-000000000005','content_manage'from app_private.events where slug='frightnight-2027-test';
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000005');
select is(jsonb_array_length(api.frightnight_snapshot('frightnight-2027-test')#>'{feedback,organizationThanks}'),1,'explicit content manager receives only the edition inbox');
update app_private.event_capabilities set revoked_at=clock_timestamp()where user_id='f7340000-0000-0000-0000-000000000005';
select ok(not(api.frightnight_snapshot('frightnight-2027-test')?'feedback'),'revoked feedback capability removes inbox immediately');
-- Closing an actually paused active evening is one transaction and retains finale.
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000001');
insert into feedback_state select 'seed',pg_temp.fb_cmd('test.seed')->'result';
select pg_temp.fb_cmd('test.walk.fixture');
select pg_temp.fb_pay('f7340000-0000-0000-0000-000000000002');
select pg_temp.fb_pay('f7340000-0000-0000-0000-000000000003');
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000002');
select pg_temp.fb_cmd('journey.start',jsonb_build_object('code',(select value->>'startCode'from feedback_state where key='seed'),'expectedVersion',1));
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000001');
select pg_temp.fb_cmd('admin.settings',jsonb_build_object('expectedVersion',(api.frightnight_snapshot('frightnight-2027-test')#>>'{event,version}')::integer,'paused',true,'reason','Synthetic global pause before close'));
select throws_ok($$select pg_temp.fb_cmd('admin.settings',jsonb_build_object('expectedVersion',-1,'closed',true))$$,'40001','VERSION_CONFLICT','stale close cannot clear a current global pause');
select is(api.frightnight_snapshot('frightnight-2027-test')#>>'{event,paused}','true','failed close preserves global pause');
insert into feedback_state select 'closePayload',jsonb_build_object('expectedVersion',(api.frightnight_snapshot('frightnight-2027-test')#>>'{event,version}')::integer,'closed',true,'reason','Synthetic closed after paused evening');
insert into feedback_state select 'close',pg_temp.fb_cmd('admin.settings',(select value from feedback_state where key='closePayload'),'f7340000-0000-0000-0000-000000000102');
select is(api.frightnight_snapshot('frightnight-2027-test')#>>'{event,paused}','false','actual close transition clears the prior global pause atomically');
select is(api.frightnight_snapshot('frightnight-2027-test')#>>'{event,closed}','true','closing does not reopen new evening admission');
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000003');
select throws_ok($$select pg_temp.fb_cmd('journey.start',jsonb_build_object('code',(select value->>'startCode'from feedback_state where key='seed'),'expectedVersion',1))$$,'22023','EDITION_CLOSED','new starts stay denied after pause-clearing close');
select throws_ok($$select pg_temp.fb_cmd('activity.book',jsonb_build_object('activityId',(select id from app_private.fn_activities limit 1)))$$,'22023','EDITION_CLOSED','new activity bookings stay denied after close');
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000002');
insert into feedback_state select 'finale',api.frightnight_snapshot('frightnight-2027-test');
select is((select value#>>'{current,zone,type}'from feedback_state where key='finale'),'finale','already running family has its controlled Duinpad return');
select lives_ok($$select pg_temp.fb_cmd('journey.complete',jsonb_build_object('destinationId',(select value#>>'{current,id}'from feedback_state where key='finale'),'expectedVersion',(select(value#>>'{journey,version}')::integer from feedback_state where key='finale'),'code',(select z->>'code'from feedback_state s cross join lateral jsonb_array_elements(s.value->'zoneCodes')z where s.key='seed'and z->>'zoneId'=(select value#>>'{current,zoneId}'from feedback_state where key='finale'))))$$,'paused-then-closed running family can really finish the final scan');
select is(api.frightnight_snapshot('frightnight-2027-test')#>>'{journey,state}','finished','finale scan finishes without fabricated ordinary visits');
select is((select count(*)from app_private.fn_visits where registration_id=app_private.fn_registration((select id from app_private.events where slug='frightnight-2027-test'),'f7340000-0000-0000-0000-000000000002')),1::bigint,'closure never gifts ordinary visits');
select pg_temp.fb_cmd('evaluation.save','{"rating":5,"text":"Duurzaam algemeen evaluatiebericht"}');
select pg_temp.fb_actor('f7340000-0000-0000-0000-000000000001');
select is(api.frightnight_snapshot('frightnight-2027-test')#>>'{feedback,evaluations,0,message}','Duurzaam algemeen evaluatiebericht','organization sees existing evaluations durably in its bounded inbox');
select pg_temp.fb_cmd('admin.settings',jsonb_build_object('expectedVersion',(api.frightnight_snapshot('frightnight-2027-test')#>>'{event,version}')::integer,'closed',false,'paused',true,'reason','Synthetic legitimate later reopen and pause'));
select lives_ok($$select pg_temp.fb_cmd('admin.settings',(select value from feedback_state where key='closePayload'),'f7340000-0000-0000-0000-000000000102')$$,'old close receipt remains replayable after a later policy change');
select is(api.frightnight_snapshot('frightnight-2027-test')#>>'{event,paused}','true','old close replay cannot clear a later legitimate pause');
select is(api.frightnight_snapshot('frightnight-2027-test')#>>'{event,closed}','false','old close replay cannot reclose a reopened edition');
select throws_ok($$select pg_temp.fb_cmd('admin.settings',(select value||'{"paused":false}'::jsonb from feedback_state where key='closePayload'),'f7340000-0000-0000-0000-000000000102')$$,'40001','IDEMPOTENCY_CONFLICT','close wrapper retains original payload hash exactly');
-- Bounded projection: insertion is solely rollback fixture setup, not a command bypass.
insert into app_private.fn_registrations(event_id,label,route_type,adults,children,max_intensity,amount_cents,run_id,synthetic)select f.event_id,'Synthetic bounded inbox '||n,'lantern',1,0,1,350,f.run_id,true from app_private.fn_events f join app_private.events e on e.id=f.event_id cross join generate_series(1,105)n where e.slug='frightnight-2027-test';
insert into app_private.fn_organization_thanks(event_id,run_id,registration_id,actor_id,message)select event_id,run_id,id,'f7340000-0000-0000-0000-000000000001','Synthetic bounded inbox fixture'from app_private.fn_registrations where label like'Synthetic bounded inbox %';
select is(jsonb_array_length(api.frightnight_snapshot('frightnight-2027-test')#>'{feedback,organizationThanks}'),100,'organization feedback snapshot is bounded independently of total messages');
select is((select count(*)from app_private.email_outbox),(select(value->>'outbox')::bigint from feedback_state where key='protected'),'thanks/closure never enqueue legacy external mail');
select is((select count(*)from app_private.payment_requests),(select(value->>'payments')::bigint from feedback_state where key='protected'),'thanks/closure preserve historical payments');
select is((select count(*)from auth.users),(select(value->>'auth')::bigint from feedback_state where key='protected'),'thanks/closure create or delete no Auth identity');
select is((select phase::text from app_private.events where id='f7340000-0000-0000-0000-000000000010'),(select value->>'legacyPhase'from feedback_state where key='protected'),'old event phase remains unchanged');
select *from finish();
rollback;
